template.script:
(function() {
    console.log('[MP] init', window.l10nArMpConfig);
    var cfg = window.l10nArMpConfig;

    if (!cfg.publicKey) {
        document.getElementById('mp-loading').style.display = 'none';
        var err = document.getElementById('mp-error');
        err.textContent = 'Error: Mercado Pago no esta configurado (falta Public Key).';
        err.style.display = 'block';
        return;
    }
    if (!cfg.amount || cfg.amount <= 0) {
        document.getElementById('mp-loading').style.display = 'none';
        var err = document.getElementById('mp-error');
        err.textContent = 'Error: El monto de la transaccion es invalido.';
        err.style.display = 'block';
        return;
    }

    var mp = new MercadoPago(cfg.publicKey, { locale: 'es-AR' });
    var bricksBuilder = mp.bricks();

    var settings = {
        initialization: { amount: Number(cfg.amount) },
        callbacks: {
            onReady: function() {
                console.log('[MP] brick ready');
                document.getElementById('mp-loading').style.display = 'none';
            },
            onSubmit: function(formData, additionalData) {
                console.log('[MP] onSubmit', formData, additionalData);
                return new Promise(function(resolve, reject) {
                    var submitData = {
                        token: formData.token,
                        payment_method_id: formData.payment_method_id,
                        payment_type_id: formData.payment_type_id || (additionalData && additionalData.paymentTypeId) || 'credit_card',
                        installments: Number(formData.installments) || 1,
                        external_reference: cfg.reference,
                        payer: {
                            email: (formData.payer && formData.payer.email) || cfg.email,
                            identification: (formData.payer && formData.payer.identification) || {},
                        },
                    };
                    console.log('[MP] sending', submitData);
                    fetch('/payment/mercado_pago/process_order', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(submitData),
                    })
                    .then(function(res) { return res.json(); })
                    .then(function(data) {
                        console.log('[MP] response', data);
                        if (data.success) {
                            window.location.href = data.redirect_url;
                        } else {
                            alert('Error: ' + (data.error || 'No se pudo procesar el pago'));
                            reject();
                        }
                        resolve();
                    })
                    .catch(function(err) {
                        console.error('[MP] fetch error', err);
                        alert('Error de conexion al procesar el pago');
                        reject();
                    });
                });
            },
            onError: function(error) {
                console.error('[MP] brick error', error);
                document.getElementById('mp-loading').style.display = 'none';
                var err = document.getElementById('mp-error');
                err.textContent = 'Error al cargar el formulario de pago. Recargue la pagina e intente nuevamente.';
                err.style.display = 'block';
            },
        },
    };
    bricksBuilder.create('cardPayment', 'cardPaymentBrick_container', settings)
    .then(function() {
        console.log('[MP] brick created');
    })
    .catch(function(error) {
        console.error('[MP] create error', error);
        document.getElementById('mp-loading').style.display = 'none';
        var err = document.getElementById('mp-error');
        err.textContent = 'Error al cargar formulario: ' + (error.message || JSON.stringify(error));
        err.style.display = 'block';
    });
})();
